// headless-verification mode: render the scene with HUD, no menu overlay
if (location.hash === '#screenshot') {
  ui.menu.classList.add('hidden');
  ui.hud.classList.add('visible');
  camera.position.set(player.pos.x, player.pos.y + player.eyeHeight, player.pos.z);
  camera.rotation.set(0, player.yaw, 0, 'YXZ');
